__d(function(g,r,i,a,m,e,d){Object.defineProperty(e,"__esModule",{value:!0}),e.LEGAL_UPDATED=e.LEGAL_ORDER=e.LEGAL_DOCS=void 0;e.LEGAL_UPDATED='2026-07-25',e.LEGAL_DOCS={terms:{title:'\uc774\uc6a9\uc57d\uad00',body:"\uc81c1\uc870 (\ubaa9\uc801)\n\uc774 \uc57d\uad00\uc740 \uc2e4\ubc84\uc2a4\ud14c\uc774(\uc774\ud558 \"\uc11c\ube44\uc2a4\")\uc758 \uc774\uc6a9\uacfc \uad00\ub828\ud558\uc5ec \uc11c\ube44\uc2a4 \uc6b4\uc601\uc790(\uc774\ud558 \"\uc6b4\uc601\uc790\")\uc640 \uc774\uc6a9\uc790 \uac04\uc758 \uad8c\ub9ac\xb7\uc758\ubb34 \ubc0f \ucc45\uc784\uc0ac\ud56d\uc744 \uc815\ud568\uc744 \ubaa9\uc801\uc73c\ub85c \ud569\ub2c8\ub2e4.\n\n\uc81c2\uc870 (\uc11c\ube44\uc2a4\uc758 \ub0b4\uc6a9)\n\u2460 \uc11c\ube44\uc2a4\ub294 \uc2dc\ub2c8\uc5b4 \uc8fc\uac70\uc2dc\uc124(\uc2e4\ubc84\ud0c0\uc6b4\xb7\uc694\uc591\uc2dc\uc124\xb7\uc7ac\uac00\ub3cc\ubd04 \ub4f1)\uc5d0 \uad00\ud55c \uc815\ubcf4 \ud0d0\uc0c9, \ube44\uc6a9 \ube44\uad50, \uc720\ud615 \uc9c4\ub2e8, \uc0c1\ub2f4\xb7\ud22c\uc5b4 \uc608\uc57d \uc2e0\uccad \uae30\ub2a5\uc744 \uc81c\uacf5\ud569\ub2c8\ub2e4.\n\u2461 \uc11c\ube44\uc2a4\uac00 \uc81c\uacf5\ud558\ub294 \uc2dc\uc124 \uc815\ubcf4(\ube44\uc6a9\xb7\uacf5\uc2e4\xb7\uc6b4\uc601 \uc815\ubcf4 \ub4f1)\ub294 \uacf5\uacf5\ub370\uc774\ud130, \uc2dc\uc124 \uacf5\uc2dd \uc790\ub8cc, \uc5b8\ub860 \ub4f1 \uacf5\uac1c \uc790\ub8cc\ub97c \uc218\uc9d1\xb7\uc815\ub9ac\ud55c \uac83\uc73c\ub85c, \ucc38\uace0\uc6a9\uc785\ub2c8\ub2e4. \uc2e4\uc81c \uc870\uac74\uc740 \uc2dc\uc124 \uc0ac\uc815\uc5d0 \ub530\ub77c \ub2e4\ub97c \uc218 \uc788\uc73c\uba70, \uacc4\uc57d \uc804 \ubc18\ub4dc\uc2dc \uc2dc\uc124\uc5d0 \uc9c1\uc811 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.\n\u2462 \uc6b4\uc601\uc790\ub294 \uc2dc\uc124\uacfc \uc774\uc6a9\uc790 \uac04 \uacc4\uc57d\uc758 \ub2f9\uc0ac\uc790\uac00 \uc544\ub2c8\uba70, \uc785\uc8fc \uacc4\uc57d\uc758 \ub0b4\uc6a9\xb7\uc774\ud589\uc5d0 \ub300\ud574 \ucc45\uc784\uc744 \uc9c0\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\n\n\uc81c3\uc870 (\uc0c1\ub2f4\xb7\ud22c\uc5b4 \uc608\uc57d)\n\u2460 \uc774\uc6a9\uc790\ub294 \ub85c\uadf8\uc778 \uc5c6\uc774 \uc0c1\ub2f4\xb7\ud22c\uc5b4 \uc608\uc57d\uc744 \uc2e0\uccad\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\u2461 \uc608\uc57d \uc2e0\uccad \uc2dc \uc785\ub825\ud55c \uc5f0\ub77d\ucc98 \ub4f1\uc740 \uc0c1\ub2f4 \uc5f0\uacb0 \ubaa9\uc801\uc73c\ub85c \ud574\ub2f9 \uc2dc\uc124 \ubc0f \ubc30\uc815\ub41c \uc0c1\ub2f4\uc0ac\uc5d0\uac8c \uc804\ub2ec\ub429\ub2c8\ub2e4(\uac1c\uc778\uc815\ubcf4 \ucc98\ub9ac\ubc29\uce68 \ucc38\uc870).\n\u2462 \uc608\uc57d\uc740 \uc2dc\uc124/\uc0c1\ub2f4\uc0ac\uc758 \ud655\uc778 \ud6c4 \ud655\uc815\ub418\uba70, \uc2e0\uccad\ub9cc\uc73c\ub85c \ud655\uc815\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\n\n\uc81c4\uc870 (\uc815\ubcf4\uc758 \uc2e0\ub8b0\ub3c4 \ud45c\uc2dc)\n\uc11c\ube44\uc2a4\ub294 \uac01 \uc815\ubcf4\uc5d0 \ucd9c\ucc98\xb7\uc2e0\ub8b0\ub3c4\xb7\ucd5c\uadfc \ud655\uc778\uc77c\uc744 \ud45c\uc2dc\ud558\ub824 \ub178\ub825\ud569\ub2c8\ub2e4. \"\uc804\ud654 \ud655\uc778 \ud544\uc694\" \ub4f1 \ud45c\uc2dc\uac00 \uc788\ub294 \uc815\ubcf4\ub294 \uac80\uc99d \uc804 \uc790\ub8cc\uc784\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4.\n\n\uc81c5\uc870 (\uae08\uc9c0\ud589\uc704)\n\uc774\uc6a9\uc790\ub294 \ub2e4\uc74c \ud589\uc704\ub97c \ud574\uc11c\ub294 \uc548 \ub429\ub2c8\ub2e4: \ud5c8\uc704 \uc608\uc57d\xb7\ub9ac\ubdf0 \uc791\uc131, \uc11c\ube44\uc2a4 \ub370\uc774\ud130\uc758 \ubb34\ub2e8 \ud06c\ub864\ub9c1\xb7\uc7ac\ud310\ub9e4, \ud0c0\uc778\uc758 \uac1c\uc778\uc815\ubcf4 \ub3c4\uc6a9, \uc11c\ube44\uc2a4 \uc6b4\uc601 \ubc29\ud574.\n\n\uc81c5\uc870\uc7582 (\uc774\uc6a9\uc790 \uc0dd\uc131 \ucf58\ud150\uce20 \xb7 \uc2e0\uace0\uc640 \uc0ad\uc81c)\n\u2460 \uc774\uc6a9\uc790\uac00 \uc791\uc131\xb7\uc5c5\ub85c\ub4dc\ud55c \ub9ac\ubdf0\xb7\uc0ac\uc9c4(\uc774\ud558 \"\uc774\uc6a9\uc790 \ucf58\ud150\uce20\")\uc758 \ub0b4\uc6a9\uc5d0 \ub300\ud55c \ucc45\uc784\uc740 \uc791\uc131\uc790\uc5d0\uac8c \uc788\uc73c\uba70, \uc9c1\uc811 \ucd2c\uc601\ud588\uac70\ub098 \uc0ac\uc6a9 \uad8c\ud55c\uc774 \uc788\ub294 \uc0ac\uc9c4\ub9cc \uc62c\ub9b4 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\u2461 \uc774\uc6a9\uc790\ub294 \ubd80\uc801\uc808\xb7\ud5c8\uc704\uc774\uac70\ub098 \uad8c\ub9ac\ub97c \uce68\ud574(\uac1c\uc778\uc815\ubcf4\xb7\ucd08\uc0c1\uad8c\xb7\uc800\uc791\uad8c \ub4f1)\ud558\ub294 \ucf58\ud150\uce20\ub97c \uc11c\ube44\uc2a4 \ub0b4 '\uc2e0\uace0' \uae30\ub2a5\uc73c\ub85c \uc2e0\uace0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\u2462 \ub85c\uadf8\uc778\ud55c \uc774\uc6a9\uc790\ub294 \ubcf8\uc778\uc774 \uc791\uc131\ud55c \ub9ac\ubdf0\xb7\uc5c5\ub85c\ub4dc\ud55c \uc0ac\uc9c4\uc744 \uc5b8\uc81c\ub4e0\uc9c0 \uc9c1\uc811 \uc0ad\uc81c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\u2463 \uc6b4\uc601\uc790\ub294 \uc2e0\uace0\ub418\uc5c8\uac70\ub098 \ubcf8 \uc57d\uad00\xb7\uad00\uacc4 \ubc95\ub839\uc5d0 \uc704\ubc18\ub418\ub294 \uc774\uc6a9\uc790 \ucf58\ud150\uce20\ub97c \uc0ac\uc804 \ud1b5\uc9c0 \uc5c6\uc774 \uc0ad\uc81c\ud558\uac70\ub098 \ub178\ucd9c\uc744 \uc81c\ud55c\ud560 \uc218 \uc788\uc73c\uba70, \ubc18\ub824\xb7\uc0ad\uc81c\ub41c \uc0ac\uc9c4\uc758 \uc6d0\ubcf8 \ud30c\uc77c\uc740 \uc9c0\uccb4 \uc5c6\uc774 \ud30c\uae30\ud569\ub2c8\ub2e4.\n\n\uc81c6\uc870 (\uc9c0\uc2dd\uc7ac\uc0b0\uad8c)\n\uc11c\ube44\uc2a4\uc758 \ud654\uba74\xb7\uad6c\uc131\xb7\uc18c\ud504\ud2b8\uc6e8\uc5b4\uc5d0 \uad00\ud55c \uad8c\ub9ac\ub294 \uc6b4\uc601\uc790\uc5d0\uac8c \uc788\uc2b5\ub2c8\ub2e4. \uc11c\ube44\uc2a4\uc5d0 \ud3ec\ud568\ub41c \uacf5\uacf5\ub370\uc774\ud130\uc758 \uc774\uc6a9\uc870\uac74\uc740 \"\ub370\uc774\ud130 \ucd9c\ucc98 \uace0\uc9c0\"\ub97c \ub530\ub985\ub2c8\ub2e4.\n\n\uc81c7\uc870 (\uba74\ucc45)\n\u2460 \uc6b4\uc601\uc790\ub294 \ubb34\ub8cc\ub85c \uc81c\uacf5\ub418\ub294 \uc815\ubcf4\uc758 \uc815\ud655\uc131\xb7\uc644\uc804\uc131\uc744 \ubcf4\uc99d\ud558\uc9c0 \uc54a\uc73c\uba70, \uc774\uc6a9\uc790\uac00 \uc815\ubcf4\ub97c \uc2e0\ub8b0\ud558\uc5ec \ud55c \uc758\uc0ac\uacb0\uc815\uc5d0 \ub300\ud574 \uace0\uc758\xb7\uc911\uacfc\uc2e4\uc774 \uc5c6\ub294 \ud55c \ucc45\uc784\uc744 \uc9c0\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\n\u2461 \ucc9c\uc7ac\uc9c0\ubcc0, \uc2dc\uc124\xb7\ud1b5\uc2e0\uc0ac\uc5c5\uc790\uc758 \uc0ac\uc815 \ub4f1 \uc6b4\uc601\uc790\uc758 \ud569\ub9ac\uc801 \ud1b5\uc81c\ub97c \ubc97\uc5b4\ub09c \uc0ac\uc720\ub85c \uc778\ud55c \uc11c\ube44\uc2a4 \uc911\ub2e8\uc5d0 \ub300\ud574 \ucc45\uc784\uc744 \uc9c0\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\n\n\uc81c8\uc870 (\ubd84\uc7c1 \ud574\uacb0)\n\uc11c\ube44\uc2a4 \uc774\uc6a9\uacfc \uad00\ub828\ud55c \ubd84\uc7c1\uc740 \ub300\ud55c\ubbfc\uad6d \ubc95\uc744 \uc900\uac70\ubc95\uc73c\ub85c \ud558\uba70, \ubbfc\uc0ac\uc18c\uc1a1\ubc95\uc0c1 \uad00\ud560\ubc95\uc6d0\uc5d0 \uc81c\uae30\ud569\ub2c8\ub2e4.\n\n\ubd80\uce59: \uc774 \uc57d\uad00\uc740 2026-07-21\ubd80\ud130 \uc801\uc6a9\ub429\ub2c8\ub2e4.\n2026-07-25 \uac1c\uc815: \uc11c\ube44\uc2a4 \uba85\uce6d \ubcc0\uacbd(\uc2e4\ubc84\uc2a4\ud14c\uc774), \uc774\uc6a9\uc790 \uc0dd\uc131 \ucf58\ud150\uce20 \uc870\ud56d(\uc81c5\uc870\uc7582) \uc2e0\uc124.\n\uc6b4\uc601\uc790: [\uc11c\ube44\uc2a4 \uc6b4\uc601\uc790\uba85] \xb7 \ubb38\uc758: [\uc5f0\ub77d\ucc98 \uc774\uba54\uc77c]"},privacy:{title:'\uac1c\uc778\uc815\ubcf4 \ucc98\ub9ac\ubc29\uce68',body:"\uc2e4\ubc84\uc2a4\ud14c\uc774(\uc774\ud558 \"\uc11c\ube44\uc2a4\")\ub294 \uac1c\uc778\uc815\ubcf4 \ubcf4\ud638\ubc95\uc5d0 \ub530\ub77c \uc774\uc6a9\uc790\uc758 \uac1c\uc778\uc815\ubcf4\ub97c \ub2e4\uc74c\uacfc \uac19\uc774 \ucc98\ub9ac\ud569\ub2c8\ub2e4.\n\n1. \uc218\uc9d1\ud558\ub294 \uac1c\uc778\uc815\ubcf4 \ud56d\ubaa9\uacfc \ubc29\ubc95\n\xb7 \uc0c1\ub2f4\xb7\ud22c\uc5b4 \uc608\uc57d: \uc5f0\ub77d\ucc98(\ud734\ub300\uc804\ud654\ubc88\ud638), \ud76c\ub9dd \uc77c\uc2dc, \ubb38\uc758 \ub0b4\uc6a9 \u2014 \uc774\uc6a9\uc790\uac00 \uc608\uc57d \ud654\uba74\uc5d0\uc11c \uc9c1\uc811 \uc785\ub825\n\xb7 \uacc4\uc815 \uc5f0\ub77d\ucc98(\uc120\ud0dd): \ub85c\uadf8\uc778 \uc774\uc6a9\uc790\uac00 '\ub0b4 \uc815\ubcf4'\uc5d0\uc11c \ud734\ub300\uc804\ud654\ubc88\ud638\ub97c \uc800\uc7a5\ud55c \uacbd\uc6b0 \u2014 \uc774\uc6a9\uc790\uac00 \uc9c1\uc811 \uc785\ub825. \uc0c1\ub2f4 \uc608\uc57d \uc790\ub3d9\uc785\ub825\xb7\uc0c1\ub2f4 \ud68c\uc2e0 \ubaa9\uc801\uc73c\ub85c\ub9cc \uc0ac\uc6a9\ud558\uba70, \uc774\uc6a9\uc790\uac00 \uc5b8\uc81c\ub4e0 '\ub0b4 \uc815\ubcf4'\uc5d0\uc11c \uc0ad\uc81c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\xb7 \ubcf4\ud638\uc790 \ub9ac\ubdf0: \uc791\uc131 \ub0b4\uc6a9(\ud56d\ubaa9\ubcc4 \ud3c9\uac00, \uc2e4\uc81c \ube44\uc6a9 \ub4f1) \u2014 \uc774\uc6a9\uc790\uac00 \uc9c1\uc811 \uc785\ub825(\uc5f0\ub77d\ucc98 \ubbf8\uc218\uc9d1)\n\xb7 \uce74\uce74\uc624 \ub85c\uadf8\uc778(\uc120\ud0dd): \ub2c9\ub124\uc784, \ud504\ub85c\ud544 \uc0ac\uc9c4, \uce74\uce74\uc624\uacc4\uc815(\uc774\uba54\uc77c) \u2014 \ub3d9\uc758 \uc2dc \uce74\uce74\uc624\ub85c\ubd80\ud130 \uc81c\uacf5\n\xb7 \uc790\ub3d9 \uc218\uc9d1: \uc11c\ube44\uc2a4 \uc774\uc6a9 \uacfc\uc815\uc5d0\uc11c \uc811\uc18d \uae30\ub85d(IP \uc8fc\uc18c, \uc811\uc18d \uc77c\uc2dc, \ubc29\ubb38 \ud398\uc774\uc9c0, \uac80\uc0c9\uc5b4\xb7\ud074\ub9ad \ub4f1 \uc774\uc6a9 \uae30\ub85d, \ube0c\ub77c\uc6b0\uc800 \uc815\ubcf4)\uc774 \uc790\ub3d9\uc73c\ub85c \uc0dd\uc131\xb7\uc218\uc9d1\ub429\ub2c8\ub2e4. \uad11\uace0 \uc2dd\ubcc4\uc790\xb7\uc704\uce58\uc815\ubcf4\ub294 \uc218\uc9d1\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\n\n2. \uc218\uc9d1\xb7\uc774\uc6a9 \ubaa9\uc801\n\xb7 \uc0c1\ub2f4 \uc5f0\uacb0: \uc608\uc57d \ub0b4\uc6a9\uc744 \ud574\ub2f9 \uc2dc\uc124 \ubc0f \ubc30\uc815 \uc0c1\ub2f4\uc0ac\uc5d0\uac8c \uc804\ub2ec\ud558\uace0 \uc0c1\ub2f4 \uc77c\uc815\uc744 \uc870\uc728\n\xb7 \uc11c\ube44\uc2a4 \uac1c\uc120: \uc774\uc6a9 \ud1b5\uacc4\xb7\ud488\uc9c8 \ubd84\uc11d(\uac1c\uc778 \uc2dd\ubcc4 \ubd88\uac00 \ud615\ud0dc)\n\xb7 \uc548\uc815 \uc6b4\uc601\xb7\ubcf4\uc548: \uc811\uc18d \uae30\ub85d \uae30\ubc18\uc758 \ubd80\uc815 \uc774\uc6a9 \ubc29\uc9c0, \uc11c\ube44\uc2a4 \uc548\uc815\uc131 \ud655\ubcf4\n\xb7 \uc811\uc18d \uae30\ub85d \ubcf4\uc720 \uae30\uac04: \uc218\uc9d1\uc77c\ub85c\ubd80\ud130 12\uac1c\uc6d4 \ud6c4 \ud30c\uae30(\ud1b5\uc2e0\ube44\ubc00\ubcf4\ud638\ubc95\uc0c1 3\uac1c\uc6d4 \uc774\uc0c1 \ubcf4\uc874 \uc758\ubb34 \uc900\uc218)\n\n3. \uc81c3\uc790 \uc81c\uacf5\n\uc0c1\ub2f4 \uc5f0\uacb0 \ubaa9\uc801\uc73c\ub85c \uc544\ub798\uc640 \uac19\uc774 \uc81c\uacf5\ub429\ub2c8\ub2e4. \uc608\uc57d \uc2e0\uccad \uc2dc \uc774\uc5d0 \ub3d9\uc758\ud55c \uac83\uc73c\ub85c \ubd05\ub2c8\ub2e4.\n\xb7 \uc81c\uacf5\ubc1b\ub294 \uc790: \uc608\uc57d \ub300\uc0c1 \uc2dc\uc124, \ubc30\uc815\ub41c \uc0c1\ub2f4\uc0ac\n\xb7 \uc81c\uacf5 \ud56d\ubaa9: \uc5f0\ub77d\ucc98, \ud76c\ub9dd \uc77c\uc2dc, \ubb38\uc758 \ub0b4\uc6a9\n\xb7 \ubcf4\uc720\xb7\uc774\uc6a9 \uae30\uac04: \uc0c1\ub2f4 \uc885\ub8cc \ud6c4 6\uac1c\uc6d4(\ubd84\uc7c1 \ub300\uc751), \uc774\ud6c4 \ud30c\uae30\n\n4. \ucc98\ub9ac \uc704\ud0c1 \ubc0f \uad6d\uc678 \uc774\uc804\n\xb7 \uc218\ud0c1\uc0ac: Supabase, Inc. (\ud074\ub77c\uc6b0\ub4dc \ub370\uc774\ud130\ubca0\uc774\uc2a4 \uc778\ud504\ub77c)\n\xb7 \uc11c\ubc84 \uc18c\uc7ac\uc9c0: \ub300\ud55c\ubbfc\uad6d(\uc11c\uc6b8 \ub9ac\uc804, AWS ap-northeast-2). \uc6b4\uc601\uc0ac\ub294 \ubbf8\uad6d \ubc95\uc778\uc73c\ub85c, \uc11c\ube44\uc2a4 \uc81c\uacf5\uc744 \uc704\ud55c \uc778\ud504\ub77c \uc6b4\uc601 \ubc94\uc704\uc5d0\uc11c \uac1c\uc778\uc815\ubcf4\uac00 \ucc98\ub9ac\ub429\ub2c8\ub2e4.\n\n5. \ubcf4\uc720 \uae30\uac04 \ubc0f \ud30c\uae30\n\xb7 \uc608\uc57d \uc815\ubcf4: \uc0c1\ub2f4 \uc885\ub8cc \ud6c4 6\uac1c\uc6d4 \ubcf4\uad00 \ud6c4 \ud30c\uae30(\uad00\uacc4 \ubc95\ub839\uc5d0 \ub530\ub978 \ubcf4\uc874 \uc758\ubb34\uac00 \uc788\ub294 \uacbd\uc6b0 \uadf8 \uae30\uac04)\n\xb7 \ud68c\uc6d0 \ud0c8\ud1f4: '\ub0b4 \uc815\ubcf4 \u2192 \ud68c\uc6d0 \ud0c8\ud1f4'\ub85c \uc5b8\uc81c\ub4e0 \uac00\ub2a5\ud558\uba70, \ud0c8\ud1f4 \uc989\uc2dc \uacc4\uc815\xb7\ud504\ub85c\ud544\xb7\ucc1c\xb7\ubcf8\uc778 \uc0c1\ub2f4 \uc774\ub825\uc774 \ubcf5\uad6c \ubd88\uac00\ub2a5\ud558\uac8c \uc0ad\uc81c\ub429\ub2c8\ub2e4.\n\xb7 \ud30c\uae30 \ubc29\ubc95: \uc804\uc790\uc801 \ud30c\uc77c\uc740 \ubcf5\uad6c \ubd88\uac00\ub2a5\ud55c \ubc29\ubc95\uc73c\ub85c \uc0ad\uc81c\n\n6. \uc774\uc6a9\uc790\uc758 \uad8c\ub9ac\n\uc774\uc6a9\uc790\ub294 \uc5b8\uc81c\ub4e0\uc9c0 \uc790\uc2e0\uc758 \uac1c\uc778\uc815\ubcf4\uc5d0 \ub300\ud55c \uc5f4\ub78c\xb7\uc815\uc815\xb7\uc0ad\uc81c\xb7\ucc98\ub9ac\uc815\uc9c0\ub97c \uc694\uad6c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ubb38\uc758: [\uc5f0\ub77d\ucc98 \uc774\uba54\uc77c]\n\n7. \uac1c\uc778\uc815\ubcf4 \ubcf4\ud638\ucc45\uc784\uc790\n\xb7 \uc131\uba85: [\ub2f4\ub2f9\uc790\uba85] \xb7 \uc5f0\ub77d\ucc98: [\uc5f0\ub77d\ucc98 \uc774\uba54\uc77c]\n\n8. \uace0\uc9c0 \uc758\ubb34\n\uc774 \ubc29\uce68\uc774 \ubcc0\uacbd\ub418\ub294 \uacbd\uc6b0 \uc2dc\ud589 7\uc77c \uc804 \uc11c\ube44\uc2a4 \ub0b4 \uacf5\uc9c0\ud569\ub2c8\ub2e4.\n\n\uc2dc\ud589\uc77c: 2026-07-21"},location:{title:'\uc704\uce58\uae30\ubc18\uc11c\ube44\uc2a4 \uc774\uc6a9\uc57d\uad00',body:"\uc81c1\uc870 (\ubaa9\uc801)\n\uc774 \uc57d\uad00\uc740 \uc2e4\ubc84\uc2a4\ud14c\uc774\uac00 \uc81c\uacf5\ud558\ub294 \uc704\uce58\uae30\ubc18\uc11c\ube44\uc2a4\uc640 \uad00\ub828\ud558\uc5ec \uc6b4\uc601\uc790\uc640 \uc774\uc6a9\uc790 \uac04\uc758 \uad8c\ub9ac\xb7\uc758\ubb34\ub97c \uc815\ud568\uc744 \ubaa9\uc801\uc73c\ub85c \ud569\ub2c8\ub2e4.\n\n\uc81c2\uc870 (\ud604\uc7ac \uc704\uce58\uc815\ubcf4 \uc218\uc9d1 \ud604\ud669)\n\u2460 \uc11c\ube44\uc2a4\uc758 \uc9c0\ub3c4 \uae30\ub2a5\uc740 \uc2dc\uc124\uc758 \uc704\uce58(\uc8fc\uc18c\xb7\uc88c\ud45c)\ub97c \ud45c\uc2dc\ud560 \ubfd0, \ud604\uc7ac \uc774\uc6a9\uc790 \ub2e8\ub9d0\uc758 \uc704\uce58\uc815\ubcf4\ub97c \uc218\uc9d1\xb7\uc774\uc6a9\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\n\u2461 \ub530\ub77c\uc11c \ud604 \uc2dc\uc810\uc758 \uc11c\ube44\uc2a4\ub294 \uc704\uce58\uc815\ubcf4\uc758 \ubcf4\ud638 \ubc0f \uc774\uc6a9 \ub4f1\uc5d0 \uad00\ud55c \ubc95\ub960\uc0c1 \uac1c\uc778\uc704\uce58\uc815\ubcf4\ub97c \ucc98\ub9ac\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\n\n\uc81c3\uc870 (\"\ub0b4 \uc8fc\ubcc0\" \uae30\ub2a5 \ub3c4\uc785 \uc2dc)\n\u2460 \ud5a5\ud6c4 \uc774\uc6a9\uc790 \uc704\uce58 \uae30\ubc18 \uae30\ub2a5(\ub0b4 \uc8fc\ubcc0 \uc2dc\uc124 \ucc3e\uae30 \ub4f1)\uc744 \ub3c4\uc785\ud558\ub294 \uacbd\uc6b0, \ub2e8\ub9d0 \uc704\uce58\uc815\ubcf4\ub294 \ud574\ub2f9 \uae30\ub2a5 \uc81c\uacf5 \ubaa9\uc801\uc73c\ub85c\ub9cc \uc77c\uc2dc \uc774\uc6a9\ub418\uba70 \uc11c\ubc84\uc5d0 \uc800\uc7a5\ud558\uc9c0 \uc54a\ub294 \ubc29\uc2dd\uc744 \uc6b0\uc120\ud569\ub2c8\ub2e4.\n\u2461 \uc704\uce58\uc815\ubcf4\ub97c \uc218\uc9d1\xb7\uc800\uc7a5\ud558\uac8c \ub418\ub294 \uacbd\uc6b0 \uc6b4\uc601\uc790\ub294 \uad00\uacc4 \ubc95\ub839\uc5d0 \ub530\ub978 \uc2e0\uace0 \ub4f1 \ud544\uc694\ud55c \uc808\ucc28\ub97c \uc774\ud589\ud558\uace0, \ubcf8 \uc57d\uad00\uc744 \uac1c\uc815\ud558\uc5ec \uace0\uc9c0\ud569\ub2c8\ub2e4.\n\n\uc81c4\uc870 (\ub3d9\uc758 \ubc0f \ucca0\ud68c)\n\uc704\uce58 \uae30\ub2a5\uc740 \ub2e8\ub9d0 \uad8c\ud55c \uc694\uccad\uc5d0 \ub300\ud55c \uc774\uc6a9\uc790\uc758 \uba85\uc2dc\uc801 \ub3d9\uc758 \ud6c4\uc5d0\ub9cc \ub3d9\uc791\ud558\uba70, \uc774\uc6a9\uc790\ub294 \ub2e8\ub9d0 \uc124\uc815\uc5d0\uc11c \uc5b8\uc81c\ub4e0\uc9c0 \ub3d9\uc758\ub97c \ucca0\ud68c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uc2dc\ud589\uc77c: 2026-07-21 \xb7 \ubb38\uc758: [\uc5f0\ub77d\ucc98 \uc774\uba54\uc77c]"},sources:{title:'\ub370\uc774\ud130 \ucd9c\ucc98 \uace0\uc9c0',body:"\uc2e4\ubc84\uc2a4\ud14c\uc774\uc758 \uc2dc\uc124 \uc815\ubcf4\ub294 \uc544\ub798 \uacf5\uac1c \uc790\ub8cc\ub97c \uc218\uc9d1\xb7\uc815\ub9ac\ud55c \uac83\uc785\ub2c8\ub2e4. \uc815\ubcf4\ub294 \ucc38\uace0\uc6a9\uc774\uba70, \ucd5c\uc2e0\xb7\uc815\ud655\ud55c \uc870\uac74\uc740 \uc2dc\uc124\uc5d0 \uc9c1\uc811 \ud655\uc778\ud558\uc2dc\uae30 \ubc14\ub78d\ub2c8\ub2e4.\n\n1. \uc804\uad6d\uc0ac\ud68c\ubcf5\uc9c0\uc2dc\uc124 \ud45c\uc900\ub370\uc774\ud130\n\xb7 \uc81c\uacf5: \ud55c\uad6d\uc0ac\ud68c\ubcf4\uc7a5\uc815\ubcf4\uc6d0(\ubcf4\uac74\ubcf5\uc9c0\ubd80 \ud45c\uc900\ub370\uc774\ud130) \xb7 \uacf5\uacf5\ub370\uc774\ud130\ud3ec\ud138(data.go.kr)\n\xb7 \uc774\uc6a9\uc870\uac74: \uc774\uc6a9\ud5c8\ub77d\ubc94\uc704 \uc81c\ud55c \uc5c6\uc74c\n\xb7 \ud65c\uc6a9: \ub178\uc778\uc8fc\uac70\xb7\uc7ac\uac00\xb7\uc694\uc591\uc2dc\uc124\uc758 \uae30\ubcf8 \uc815\ubcf4(\uba85\uce6d\xb7\uc8fc\uc18c\xb7\uc720\ud615 \ub4f1)\n\n2. \ubcd1\uc6d0\uc815\ubcf4\uc11c\ube44\uc2a4\n\xb7 \ubcf8 \uc11c\ube44\uc2a4\ub294 \uac74\uac15\ubcf4\ud5d8\uc2ec\uc0ac\ud3c9\uac00\uc6d0\uc5d0\uc11c \uc791\uc131\ud558\uc5ec \uacf5\uacf5\ub204\ub9ac \uc81c1\uc720\ud615\uc73c\ub85c \uac1c\ubc29\ud55c \"\ubcd1\uc6d0\uc815\ubcf4\uc11c\ube44\uc2a4\"\ub97c \uc774\uc6a9\ud558\uc600\uc2b5\ub2c8\ub2e4. (www.data.go.kr)\n\xb7 \ud65c\uc6a9: \uc694\uc591\ubcd1\uc6d0 \uae30\ubcf8 \uc815\ubcf4(\uba85\uce6d\xb7\uc8fc\uc18c\xb7\uc88c\ud45c\xb7\uc804\ud654)\n\n3. \uc2dc\uc124 \uacf5\uc2dd \uc790\ub8cc\xb7\uc5b8\ub860 \ubcf4\ub3c4\n\xb7 \ube44\uc6a9(\ubcf4\uc99d\uae08\xb7\uc6d4 \uc774\uc6a9\ub8cc\xb7\uc2dd\ube44) \uc815\ubcf4\ub294 \uac01 \uc2dc\uc124 \uacf5\uc2dd \ud648\ud398\uc774\uc9c0, \uc5b8\ub860 \ubcf4\ub3c4 \ub4f1 \uacf5\uac1c \uc790\ub8cc \uae30\uc900\uc774\uba70, \uac01 \uc2dc\uc124 \uc0c1\uc138 \ud654\uba74\uc5d0 \uac1c\ubcc4 \ucd9c\ucc98\uc640 \uc2e0\ub8b0\ub3c4(\uacf5\uc2dd/2\ucc28\uc790\ub8cc)\xb7\ucd5c\uadfc \ud655\uc778\uc77c\uc744 \ud45c\uc2dc\ud569\ub2c8\ub2e4.\n\xb7 \ud574\ub2f9 \uc815\ubcf4\ub294 \uc2dc\uc124 \uc0ac\uc815\uc5d0 \ub530\ub77c \ubcc0\ub3d9\ub420 \uc218 \uc788\uc5b4 \"\uc804\ud654 \ud655\uc778 \ud544\uc694\" \ub77c\ubca8\uacfc \ud568\uaed8 \uc81c\uacf5\ub429\ub2c8\ub2e4.\n\n4. \uc9c0\ub3c4\n\xb7 \uc9c0\ub3c4 \ud0c0\uc77c: \xa9 OpenStreetMap contributors (\uc624\ud508 \ub77c\uc774\uc120\uc2a4)\n\n\ubb38\uc758\xb7\uc815\uc815 \uc694\uccad: [\uc5f0\ub77d\ucc98 \uc774\uba54\uc77c]\n\uac31\uc2e0\uc77c: 2026-07-21"}},e.LEGAL_ORDER=['terms','privacy','location','sources']},934,[]);